package com.ecommerce.service;
import com.ecommerce.dto.PaymentDtos.*; import com.ecommerce.exception.ApiException; import com.ecommerce.model.*; import com.ecommerce.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class PaymentService { private final PaymentRepository payments; private final OrderRepository orders; public PaymentService(PaymentRepository payments,OrderRepository orders){this.payments=payments;this.orders=orders;} @Transactional public PaymentResponse pay(User user,PaymentRequest r){ Order o=orders.findById(r.orderId()).filter(order->order.getUser().getId().equals(user.getId())).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Order not found")); if(o.getStatus()!=OrderStatus.PENDING) throw new ApiException(HttpStatus.BAD_REQUEST,"Only pending orders can be paid"); Payment p=payments.findByOrder(o).orElseGet(Payment::new); p.setOrder(o); p.setProvider(r.provider()); p.setAmount(o.getTotalAmount()); p.setTransactionId((r.provider()==PaymentProvider.RAZORPAY?"rzp_mock_":"mock_")+UUID.randomUUID()); p.setStatus(PaymentStatus.SUCCESS); o.setStatus(OrderStatus.PAID); orders.save(o); return toResponse(payments.save(p)); } public PaymentResponse toResponse(Payment p){ return new PaymentResponse(p.getId(),p.getOrder().getId(),p.getProvider(),p.getStatus(),p.getAmount(),p.getTransactionId()); } }